     /// Replaces the special payload. Any version is accepted.
     pub fn set_payload(&mut self, payload: Payload) {
         self.payload = Some(payload);
     }

     fn fee(&self, p: &Payload) -> u64 {
         (self.base_size() + self.estimated_payload_size(p)) as u64 * MIN_RELAY_FEE_PER_BYTE
     }

     fn estimated_payload_size(&self, p: &Payload) -> usize {
         match p.version {
             1 | 2 => 2 + 32 + 48 + varint_size(p.script.len()) + p.script.len(),
+            3 => 2 + 32 + 48,
             _ => 0,
         }
